import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.BGkQCay2.js";const u=JSON.parse('{"title":"Versioning and Stability","description":"","frontmatter":{},"headers":[],"relativePath":"guide/versioning.md","filePath":"guide/versioning.md"}'),n={name:"guide/versioning.md"};function o(s,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="versioning-and-stability" tabindex="-1">Versioning and Stability <a class="header-anchor" href="#versioning-and-stability" aria-label="Permalink to &quot;Versioning and Stability&quot;">​</a></h1><p>Vex is pre-1.0. Version numbers describe compiler releases, not a promise that every documented feature is production-ready.</p><h2 id="current-release" tabindex="-1">Current release <a class="header-anchor" href="#current-release" aria-label="Permalink to &quot;Current release&quot;">​</a></h2><p>The compiler version used for this documentation pass is <code>0.4.0-rc.39</code>. Always verify the binary you are using:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>The <a href="/docs/guide/language-status">language status matrix</a> is the source of truth for the current maturity of language and runtime features.</p><h2 id="version-policy" tabindex="-1">Version policy <a class="header-anchor" href="#version-policy" aria-label="Permalink to &quot;Version policy&quot;">​</a></h2><p>Vex follows a SemVer-inspired policy. Before 1.0, minor releases may contain breaking language, compiler, or standard-library changes.</p><table tabindex="0"><thead><tr><th>Change</th><th>Typical release level</th><th>Pre-1.0 expectation</th></tr></thead><tbody><tr><td>Backward-compatible bug fix</td><td>Patch</td><td>Still verify generated code and runtime behavior.</td></tr><tr><td>New or changed feature</td><td>Minor</td><td>May require source changes.</td></tr><tr><td>Major compatibility break</td><td>Major</td><td>Reserved for broad migrations, but not the only possible breaking change before 1.0.</td></tr></tbody></table><p>Release candidates should be treated as testable snapshots. Pin the compiler in CI and record the target platform when reporting a result.</p><h2 id="stability-labels" tabindex="-1">Stability labels <a class="header-anchor" href="#stability-labels" aria-label="Permalink to &quot;Stability labels&quot;">​</a></h2><ul><li><strong>Verified:</strong> The syntax or behavior is supported by the current compiler checks or a maintained implementation path.</li><li><strong>Experimental:</strong> The compiler accepts the surface, but runtime, backend, or library behavior is still changing.</li><li><strong>Partial:</strong> The main surface exists, while important integration or edge cases remain unfinished.</li><li><strong>Planned:</strong> The concept is documented for direction only and should not be used as current syntax.</li></ul><p>These labels are more precise than a single stable/unstable tier because a feature can be compiler-complete while its runtime support is incomplete.</p><h2 id="upgrading-safely" tabindex="-1">Upgrading safely <a class="header-anchor" href="#upgrading-safely" aria-label="Permalink to &quot;Upgrading safely&quot;">​</a></h2><ol><li>Read the changelog and compare the compiler version with <code>vex --version</code>.</li><li>Run <code>vex lint</code> on the project before and after upgrading.</li><li>Run the project&#39;s tests on every target platform it supports.</li><li>Recheck pages marked Experimental or Partial in the language-status matrix.</li><li>Keep a small set of representative source examples in CI.</li></ol><p>Design notes and old migration documents may describe intended syntax. They are not authoritative when they disagree with compiler checks or the current language guide.</p><h2 id="reporting-a-compatibility-problem" tabindex="-1">Reporting a compatibility problem <a class="header-anchor" href="#reporting-a-compatibility-problem" aria-label="Permalink to &quot;Reporting a compatibility problem&quot;">​</a></h2><p>Include the compiler version, platform, command, source file, and complete diagnostic. If the problem is in the compiler or bundled runtime rather than the user program, record it in the repository issue tracker and link the report from the relevant documentation page.</p>',18)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
